cd /scr/wurgaft/auto-psych/agent_trees/d6b6238b22d937a5/repo/_runs/cell_1/experiment2/model_loop; python3 -c "
import csv,collections
P={p for p in range(2,101) if all(p%d for d in range(2,int(p**.5)+1))}
d=collections.defaultdict(list)
for r in csv.DictReader(open('responses.csv')):
  ex=[int(x) for x in r['number_set'].split(',')]
  if len(ex)>=2 and all(e in P for e in ex): d[r['number_set']].append((int(r['target']),int(r['rating'])))
for s,v in d.items():
  agg=collections.defaultdict(list)
  for t,y in v: agg[t].append(y)
  print(s, sorted((t,'P' if t in P else ('o' if t%2 else 'e'),round(sum(y)/len(y),2),len(y)) for t,y in agg.items()))
"; wc -l responses.csv; cat models/models_manifest.yaml | head -60

